# Python3.8 兼容 asyncio.to_thread
if hasattr(asyncio, "to_thread"):
    to_thread = asyncio.to_thread
else:
    async def to_thread(func, *args, **kwargs):
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, partial(func, *args, **kwargs))



def _stamp_seconds(stamp: Any) -> float:
    return float(stamp.sec) + float(stamp.nanosec) / 1_000_000_000.0


def _route_points(route: Any) -> List[List[float]]:
    try:
        return [[float(p.point.x), float(p.point.y)] for p in route.main_trajectory.waypoints]
    except (AttributeError, TypeError):
        return []


def _state_json(state: NavigationState) -> Dict[str, Any]:
    p = state.vehicle_pose
    e = state.effective_endpoint
    return {
        "manager_boot_id": state.manager_boot_id,
        "state_revision": int(state.state_revision),
        "timestamp": _stamp_seconds(state.header.stamp),
        "map_ready": bool(state.map_ready),
        "map_version": state.map_version,
        "map_name": state.map_name,
        "frame_id": state.frame_id,
        "pose_fresh": bool(state.pose_fresh),
        "navigation_synchronized": bool(state.navigation_synchronized),
        "vehicle": {
            "x": float(p.position.x), "y": float(p.position.y), "z": float(p.position.z),
            "qx": float(p.orientation.x), "qy": float(p.orientation.y),
            "qz": float(p.orientation.z), "qw": float(p.orientation.w),
            "vx": float(state.linear_velocity.x), "vy": float(state.linear_velocity.y),
            "wz": float(state.angular_velocity.z),
        },
        "control": {
            "held": bool(state.control_held), "owner_label": state.control_owner_label,
            "epoch": int(state.control_epoch),
        },
        "task": {
            "id": state.task_id, "ros_goal_uuid": state.ros_goal_uuid,
            "status": int(state.task_status), "status_text": state.task_status_text,
            "request_id": state.request_id,
            "device_label": state.task_device_label,
            "requested": {"x": float(state.requested_x), "y": float(state.requested_y)},
            "endpoint": {"x": float(e.position.x), "y": float(e.position.y), "z": float(e.position.z),
                         "qz": float(e.orientation.z), "qw": float(e.orientation.w)},
            "path_revision": int(state.path_revision), "route": _route_points(state.route),
            "error_code": state.error_code, "error_message": state.error_message,
            "sequence": [{"annotation_id": p.annotation_id, "name": p.name, "x": p.x,
                          "y": p.y, "lanelet_id": p.lanelet_id, "stop": p.stop} for p in state.sequence],
            "sequence_index": int(state.sequence_index), "sequence_state": state.sequence_state,
            "sequence_loop": bool(state.sequence_loop),
        },
    }


class StateHub:
    def __init__(self) -> None:
        self.loop: Optional[asyncio.AbstractEventLoop] = None
        self.latest: Optional[Dict[str, Any]] = None
        self.queues: Set[asyncio.Queue] = set()
        self.gateway_boot_id = secrets.token_hex(16)
        self.event_seq = 0

    def attach(self, loop: asyncio.AbstractEventLoop) -> None:
        self.loop = loop

    def publish_from_ros(self, message: NavigationState) -> None:
        if self.loop is None:
            return
        payload = {"type": "state", "state": _state_json(message)}
        self.loop.call_soon_threadsafe(self._publish, payload)

    def publish(self, payload: Dict[str, Any]) -> None:
        if self.loop is None:
            return
        self._publish(payload)

    def envelope(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        self.event_seq += 1
        current_state = payload.get("state") or self.latest or {}
        body = {key: value for key, value in payload.items() if key != "type"}
        return {
            **payload,
            "gateway_boot_id": self.gateway_boot_id,
            "manager_boot_id": current_state.get("manager_boot_id", ""),
            "event_seq": self.event_seq,
            "state_revision": int(current_state.get("state_revision", 0)),
            "payload": body,
        }

    def enqueue(self, queue: asyncio.Queue, payload: Dict[str, Any]) -> None:
        message = self.envelope(payload)
        if queue.full():
            old_state = next((item for item in queue._queue if item.get("type") == "state"), None)
            if old_state is not None:
                queue._queue.remove(old_state)
            else:
                queue.get_nowait()
        queue.put_nowait(message)

    def _publish(self, payload: Dict[str, Any]) -> None:
        if payload.get("type") == "state":
            self.latest = payload["state"]
        message = self.envelope(payload)
        for queue in tuple(self.queues):
            queued = queue._queue  # bounded per-client queue; move coalesced frames to their new sequence position
            if message.get("type") == "state":
                removed = False
                for index in range(len(queued) - 1, -1, -1):
                    if queued[index].get("type") == "state":
                        del queued[index]
                        removed = True
                        break
                if not removed and queue.full():
                    continue
                queue.put_nowait(message)
                continue
            if message.get("type") == "annotation":
                key = message.get("id") or message.get("item", {}).get("id")
                for index in range(len(queued) - 1, -1, -1):
                    item = queued[index]
                    item_key = item.get("id") or item.get("item", {}).get("id")
                    if item.get("type") == "annotation" and item_key == key:
                        del queued[index]
                        break
                if queue.full():
                    old_state = next((item for item in queued if item.get("type") == "state"), None)
                    if old_state is not None:
                        queued.remove(old_state)
                    else:
                        queue.get_nowait()
                queue.put_nowait(message)
                continue
            try:
                queue.put_nowait(message)
            except asyncio.QueueFull:
                try:
                    queue.get_nowait()
                    queue.put_nowait(message)
                except (asyncio.QueueEmpty, asyncio.QueueFull):
                    pass


HUB = StateHub()
ENVIRONMENT: Optional[EnvironmentStore] = None


class RosBridge(Node):
    SERVICE_TYPES = {
        "control": ("/web_nav/control_lease", ControlLease),
        "validate": ("/web_nav/validate_target", ValidateTarget),
        "submit": ("/web_nav/submit_goal", SubmitGoal),
        "cancel": ("/web_nav/cancel_task", CancelTask),
        "snapshot": ("/web_nav/get_snapshot", GetSnapshot),
        "request": ("/web_nav/get_request", GetRequest),
        "task": ("/web_nav/get_task", GetTask),
        "map": ("/web_nav/get_map", GetWebMap),
    }

    def __init__(self) -> None:
        global ENVIRONMENT
        super().__init__("nav_web_gateway")
        ENVIRONMENT = EnvironmentStore()
        self.environment_subscription = self.create_subscription(
            PointCloud2, os.environ.get("NAV_WEB_POINTCLOUD_TOPIC", "/points_map"), ENVIRONMENT.submit,
            QoSProfile(depth=1, durability=DurabilityPolicy.TRANSIENT_LOCAL,
                       reliability=ReliabilityPolicy.RELIABLE),
        )
        self.service_clients = {
            key: self.create_client(service_type, name)
            for key, (name, service_type) in self.SERVICE_TYPES.items()
        }
        self.state_subscription = self.create_subscription(
            NavigationState, "/web_nav/state", HUB.publish_from_ros, 10
        )

    async def call(self, key: str, request: Any, timeout: float = 2.0) -> Any:
        client = self.service_clients[key]
        # ready = await to_thread(client.wait_for_service, timeout_sec=min(timeout, 0.5))
        ready = await to_thread(client.wait_for_service, timeout_sec=min(timeout, 0.5))


        if not ready:
            raise HTTPException(status_code=503, detail="车辆任务管理器服务暂不可用")
        loop = asyncio.get_running_loop()
        result: asyncio.Future[Any] = loop.create_future()
        ros_future = client.call_async(request)

        def done(future: Any) -> None:
            def deliver() -> None:
                if result.done():
                    return
                try:
                    result.set_result(future.result())
                except Exception as error:  # surfaced to HTTP as unavailable
                    result.set_exception(error)
            loop.call_soon_threadsafe(deliver)

        ros_future.add_done_callback(done)
        try:
            return await asyncio.wait_for(result, timeout=timeout)
        except asyncio.TimeoutError as error:
            raise HTTPException(status_code=504, detail="等待车端响应超时") from error
        except HTTPException:
            raise
        except Exception as error:
            raise HTTPException(status_code=503, detail="车辆任务管理器通信失败") from error


class Session(BaseModel):
    id: str
    device_label: str
    created_at: float
    last_heartbeat: float = 0.0
    token: str = ""
    epoch: int = 0
    manager_boot_id: str = ""
    websocket_connected: bool = False
    websocket_generation: int = 0


SESSIONS: Dict[str, Session] = {}
SESSION_QUEUES: Dict[str, asyncio.Queue] = {}
SESSION_LIMIT = 16
ANNOTATION_LOCK = asyncio.Lock()
ANNOTATION_DB: Optional[sqlite3.Connection] = None
BRIDGE: Optional[RosBridge] = None
EXECUTOR: Optional[MultiThreadedExecutor] = None
EXECUTOR_THREAD: Optional[threading.Thread] = None
HEARTBEAT_TASK: Optional[asyncio.Task] = None


def _annotation_path() -> Path:
    return Path(os.environ.get("NAV_WEB_ANNOTATION_DB", "/var/lib/nav_web/annotations.sqlite"))


def _init_annotation_db() -> sqlite3.Connection:
    path = _annotation_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(str(path), check_same_thread=False, isolation_level=None)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("PRAGMA synchronous=FULL")
    connection.execute("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value INTEGER NOT NULL)")
    connection.execute("INSERT OR IGNORE INTO meta(key,value) VALUES('revision',0)")
    connection.execute("""CREATE TABLE IF NOT EXISTS annotations (
        id TEXT PRIMARY KEY, name TEXT NOT NULL, map_version TEXT NOT NULL,
        coordinate_revision TEXT NOT NULL, frame_id TEXT NOT NULL,
        x REAL NOT NULL, y REAL NOT NULL, lanelet_id TEXT NOT NULL,
        revision INTEGER NOT NULL, updated_at REAL NOT NULL, updated_by TEXT NOT NULL)""")
    columns = {row[1] for row in connection.execute("PRAGMA table_info(annotations)")}
    for name, definition in {"map_name": "TEXT NOT NULL DEFAULT ''", "nav_x": "REAL",
                             "nav_y": "REAL", "navigation_valid": "INTEGER NOT NULL DEFAULT 1"}.items():
        if name not in columns:
            connection.execute(f"ALTER TABLE annotations ADD COLUMN {name} {definition}")
    connection.execute("UPDATE annotations SET nav_x=x,nav_y=y WHERE nav_x IS NULL OR nav_y IS NULL")
    connection.execute("CREATE TABLE IF NOT EXISTS map_binding (key TEXT PRIMARY KEY,value TEXT NOT NULL)")
    return connection


def _same_origin(request: Request) -> None:
    origin = request.headers.get("origin")
    if not origin:
        return
    host = request.headers.get("host", "")
    forwarded_proto = request.headers.get("x-forwarded-proto", request.url.scheme)
    from urllib.parse import urlparse
    parsed = urlparse(origin)
    if parsed.netloc.lower() != host.lower() or parsed.scheme != forwarded_proto:
        raise HTTPException(status_code=403, detail="跨站请求已拒绝")


def _session(session_id: Optional[str]) -> Session:
    if not session_id or session_id not in SESSIONS:
        raise HTTPException(status_code=401, detail="页面会话已失效，请刷新页面")
    return SESSIONS[session_id]


def _state_for(session: Session, state: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    if state is None:
        state = HUB.latest
    if state is None:
        raise HTTPException(status_code=503, detail="尚未收到车端状态")
    copy = dict(state)
    control = dict(state["control"])
    control["owned_by_me"] = bool(session.token and control["held"] and control["epoch"] == session.epoch and state["manager_boot_id"] == session.manager_boot_id)
    copy["control"] = control
    return copy


def _require_control(session: Session, token: Optional[str], epoch: Optional[str]) -> Tuple[str, int, str]:
    if not session.token or not token or not secrets.compare_digest(session.token, token):
        raise HTTPException(status_code=403, detail="当前设备没有操作权限")
    try:
        supplied_epoch = int(epoch or "")
    except ValueError as error:
        raise HTTPException(status_code=403, detail="操作权限代次无效") from error
    if supplied_epoch != session.epoch:
        raise HTTPException(status_code=403, detail="操作权限已更新，请重新获取")
    return session.token, session.epoch, session.manager_boot_id


def _lease_identity(session: Session) -> Tuple[str, int, str]:
    return session.token, session.epoch, session.manager_boot_id


def _forget_control(session: Session, identity: Tuple[str, int, str], reason: str) -> None:
    # An old RELEASE/RENEW reply must not invalidate a subsequently acquired lease.
    if not identity[0] or _lease_identity(session) != identity:
        return
    session.token = ""
    queue = SESSION_QUEUES.get(session.id)
    if queue is not None:
        HUB.enqueue(queue, {"type": "control_lost", "message": reason,
                           "control_epoch": identity[1], "lease_manager_boot_id": identity[2]})


async def _validate_lease(session: Session, token: str, epoch: int, boot_id: str) -> None:
    request = ControlLease.Request()
    request.operation = ControlLease.Request.VALIDATE
    request.session_id = session.id
    request.manager_boot_id = boot_id
    request.lease_token = token
    request.control_epoch = epoch
    response = await BRIDGE.call("control", request)  # type: ignore[union-attr]
    if not response.success:
        _forget_control(session, (token, epoch, boot_id), response.message or "操作权限已失效")
        raise HTTPException(status_code=403, detail=response.message or "操作权限已失效")


def _target_request(model: "TargetInput", state: Dict[str, Any]) -> ValidateTarget.Request:
    request = ValidateTarget.Request()
    request.map_version = model.map_version
    request.frame_id = model.frame_id
    request.x = model.x
    request.y = model.y
    request.selected_layer_id = model.selected_layer_id or ""
    request.suggest_nearest = model.suggest_nearest
    return request


class SessionInput(BaseModel):
    device_label: str = Field(default="浏览器", max_length=64)


