    _same_origin(request)
    session = _session(session_id)
    snapshot = await _latest_state()
    if not snapshot["map_ready"] or not snapshot["pose_fresh"]:
        raise HTTPException(status_code=503, detail="地图或定位尚未就绪")
    req = ControlLease.Request()
    req.operation = ControlLease.Request.ACQUIRE
    req.session_id = session.id
    req.device_label = session.device_label
    req.manager_boot_id = snapshot["manager_boot_id"]
    result = await BRIDGE.call("control", req)  # type: ignore[union-attr]
    if not result.success:
        _service_error(result.code, result.message)
    session.token = result.lease_token
    session.epoch = int(result.control_epoch)
    session.manager_boot_id = result.manager_boot_id
    session.last_heartbeat = time.monotonic()
    return {"owned": True, "control_token": session.token,
            "control_epoch": session.epoch, "manager_boot_id": session.manager_boot_id,
            "lease_ttl_ms": int(result.lease_ttl_ms)}


