async def _submit_goal(body: GoalInput, operation: int, session: Session, token: Optional[str], epoch: Optional[str]) -> JSONResponse:
    control_token, control_epoch, boot_id = _require_control(session, token, epoch)
    req = SubmitGoal.Request()
    req.operation = operation
    req.request_id = body.request_id
    req.session_id = session.id
    req.device_label = session.device_label
    req.manager_boot_id = boot_id
    req.lease_token = control_token
    req.control_epoch = control_epoch
    req.map_version = body.map_version
    req.frame_id = body.frame_id
    req.x = body.x
    req.y = body.y
    req.selected_layer_id = body.selected_layer_id
    req.expected_active_task_id = body.expected_active_task_id
    req.expected_state_revision = body.expected_state_revision
    if body.sequence:
        if operation not in (SubmitGoal.Request.SUBMIT, SubmitGoal.Request.REPLACE):
            raise HTTPException(status_code=422, detail="顺序列表只能用于创建或替换任务")
        snapshot = await _annotation_snapshot(body.map_version)
        items = {item["id"]: item for item in snapshot["items"]}
        for selected in body.sequence:
            item = items.get(selected.annotation_id)
            if not item or item["revision"] != selected.revision:
                raise HTTPException(status_code=409, detail="停靠点已变化，请重新选择后执行")
            if not item["navigation_valid"]:
                raise HTTPException(status_code=422, detail=f"停靠点「{item['name']}」需要重新确认导航位置")
            point = SequenceWaypoint()
            point.annotation_id = item["id"]
            point.name = item["name"]
            point.x, point.y = item["nav_x"], item["nav_y"]
            point.lanelet_id, point.stop = item["lanelet_id"], selected.stop
            req.sequence.append(point)
    try:
        result = await BRIDGE.call("submit", req)  # type: ignore[union-attr]
    except HTTPException as error:
        if error.status_code != 504:
            raise
        recovered = await _request_after_timeout(body.request_id)
        if recovered is None or not recovered.found:
            raise HTTPException(status_code=504, detail={"code": "REQUEST_UNCONFIRMED",
                "message": "车端响应超时，暂未查到受理记录；请先查询此编号，不要立即创建新请求",
                "request_id": body.request_id}) from error
        if not recovered.accepted:
            _service_error(recovered.code, recovered.message)
        result = SimpleNamespace(accepted=True, request_id=body.request_id,
            task_id=recovered.task_id, task_status=recovered.task_status,
            state_revision=recovered.state_revision, message=recovered.message)
    if not result.accepted:
        _service_error(result.code, result.message)
    return JSONResponse(status_code=202, content={"accepted": True, "request_id": result.request_id,
        "task_id": result.task_id, "status": int(result.task_status), "state_revision": int(result.state_revision),
        "message": result.message})


