async def _annotation_snapshot(map_version: str) -> Dict[str, Any]:
    assert ANNOTATION_DB is not None
    current_map = await BRIDGE.call("map", GetWebMap.Request())
    if not current_map.ready or current_map.map_version != map_version:
        return {"revision": 0, "items": [], "stale_count": 0}
    if not current_map.map_name:
        raise HTTPException(status_code=503, detail="活动地图缺少名称，请更新地图加载器")
    async with ANNOTATION_LOCK:
        current_map = await BRIDGE.call("map", GetWebMap.Request())
        if not current_map.ready or current_map.map_version != map_version or not current_map.map_name:
            raise HTTPException(status_code=409, detail="地图已变化，请刷新停靠点")
        db = ANNOTATION_DB
        binding = dict(db.execute("SELECT key,value FROM map_binding").fetchall())
        old_name = binding.get("map_name")
        rows = [dict(row) for row in db.execute("SELECT * FROM annotations ORDER BY name COLLATE NOCASE,id")]
        name_changed = old_name is not None and old_name != current_map.map_name
        if name_changed:
            rows = []
        elif old_name is None:
            # Only legacy rows demonstrably belonging to the current content
            # can be assigned a name during the one-time schema migration.
            rows = [row for row in rows if row["map_version"] == map_version]
        changed = binding.get("map_version") != map_version or old_name != current_map.map_name
        if changed:
            for item in rows:
                request = ValidateTarget.Request()
                request.map_version, request.frame_id = map_version, current_map.frame_id
                request.x, request.y = item["nav_x"], item["nav_y"]
                verdict = await BRIDGE.call("validate", request)
                if verdict.code in {"MAP_VERSION_MISMATCH", "MAP_NOT_READY"}:
                    _service_error(verdict.code, verdict.message)
                item["navigation_valid"] = int(verdict.valid and item["frame_id"] == current_map.frame_id)
                item["lanelet_id"] = verdict.lanelet_ids[0] if verdict.valid and verdict.lanelet_ids else ""
            latest_map = await BRIDGE.call("map", GetWebMap.Request())
            if not latest_map.ready or latest_map.map_version != map_version or latest_map.map_name != current_map.map_name:
                raise HTTPException(status_code=409, detail="地图已变化，请刷新停靠点")
            db.execute("BEGIN IMMEDIATE")
            try:
                revision = int(db.execute("SELECT value FROM meta WHERE key='revision'").fetchone()[0]) + 1
                if name_changed:
                    db.execute("DELETE FROM annotations")
                elif old_name is None:
                    db.execute("DELETE FROM annotations WHERE map_version<>?", (map_version,))
                for item in rows:
                    db.execute("""UPDATE annotations SET map_name=?,map_version=?,coordinate_revision=?,
                        lanelet_id=?,navigation_valid=?,revision=? WHERE id=?""",
                        (current_map.map_name, map_version, current_map.coordinate_revision,
                         item["lanelet_id"], item["navigation_valid"], revision, item["id"]))
                db.execute("UPDATE meta SET value=? WHERE key='revision'", (revision,))
                for key, value in {"map_name": current_map.map_name, "map_version": map_version}.items():
                    db.execute("INSERT OR REPLACE INTO map_binding VALUES(?,?)", (key, value))
                db.execute("COMMIT")
            except Exception:
                db.execute("ROLLBACK")
                raise
        items = [dict(row) for row in db.execute("SELECT * FROM annotations ORDER BY name COLLATE NOCASE,id")]
        revision = int(db.execute("SELECT value FROM meta WHERE key='revision'").fetchone()[0])
    if changed:
        HUB.publish({"type": "annotations_reset", "annotations": items, "map_name": current_map.map_name,
                     "map_version": map_version, "revision": revision})
    return {"revision": revision, "items": items,
            "stale_count": sum(not item["navigation_valid"] for item in items)}


