async def _validate_annotation_mutation(session: Session, token: Optional[str], epoch: Optional[str],
                                        body: AnnotationInput) -> str:
    if not body.name.strip():
        raise HTTPException(status_code=422, detail="停靠点名称不能为空")
    control_token, control_epoch, boot_id = _require_control(session, token, epoch)
    await _validate_lease(session, control_token, control_epoch, boot_id)
    current_map = await BRIDGE.call("map", GetWebMap.Request())
    if not current_map.ready or body.map_version != current_map.map_version or body.frame_id != current_map.frame_id:
        raise HTTPException(status_code=409, detail="地图已更新，请刷新后再保存停靠点")
    if body.map_name and body.map_name != current_map.map_name:
        raise HTTPException(status_code=409, detail="地图名称已变化，请刷新后再保存停靠点")
    await _annotation_snapshot(body.map_version)
    if (body.nav_x is None) != (body.nav_y is None):
        raise HTTPException(status_code=422, detail="请完整指定导航位置")
    if body.nav_x is None:
        body.nav_x, body.nav_y = body.x, body.y
    nav = TargetInput(map_version=body.map_version, frame_id=body.frame_id,
                      x=body.nav_x, y=body.nav_y, selected_layer_id=body.selected_layer_id)
    verdict = await BRIDGE.call("validate", _target_request(nav, await _latest_state()))
    if not verdict.valid:
        _service_error(verdict.code, verdict.message)
    body.map_name = current_map.map_name
    body.lanelet_id = verdict.lanelet_ids[0] if verdict.lanelet_ids else ""
    return control_token


async def _write_annotation(body: AnnotationInput, session: Session, annotation_id: Optional[str] = None) -> Dict[str, Any]:
    assert ANNOTATION_DB is not None
    async with ANNOTATION_LOCK:
        db = ANNOTATION_DB
        binding = dict(db.execute("SELECT key,value FROM map_binding").fetchall())
        if binding.get("map_name") != body.map_name or binding.get("map_version") != body.map_version:
            raise HTTPException(status_code=409, detail="地图已变化，请重新保存停靠点")
        db.execute("BEGIN IMMEDIATE")
        try:
            existing = db.execute("SELECT revision FROM annotations WHERE id=?", (annotation_id,)).fetchone() if annotation_id else None
            if annotation_id and existing is None:
                raise HTTPException(status_code=404, detail="停靠点不存在")
            if existing and body.expected_revision != int(existing["revision"]):
                raise HTTPException(status_code=409, detail="停靠点已在其他设备上修改，请刷新后重试")
            if annotation_id is None:
                annotation_id = secrets.token_urlsafe(12)
            revision = int(db.execute("SELECT value FROM meta WHERE key='revision'").fetchone()[0]) + 1
            db.execute("UPDATE meta SET value=? WHERE key='revision'", (revision,))
            db.execute("""INSERT INTO annotations(id,name,map_version,coordinate_revision,frame_id,x,y,lanelet_id,
                revision,updated_at,updated_by,map_name,nav_x,nav_y,navigation_valid)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1) ON CONFLICT(id) DO UPDATE SET name=excluded.name,
                map_version=excluded.map_version,coordinate_revision=excluded.coordinate_revision,frame_id=excluded.frame_id,
                x=excluded.x,y=excluded.y,lanelet_id=excluded.lanelet_id,revision=excluded.revision,
                updated_at=excluded.updated_at,updated_by=excluded.updated_by,map_name=excluded.map_name,
                nav_x=excluded.nav_x,nav_y=excluded.nav_y,navigation_valid=1""",
                (annotation_id, body.name.strip(), body.map_version, "local-map-v1", body.frame_id,
                 body.x, body.y, body.lanelet_id, revision, time.time(), session.device_label,
                 body.map_name, body.nav_x, body.nav_y))
            db.execute("COMMIT")
        except Exception:
            db.execute("ROLLBACK")
            raise
        item = dict(db.execute("SELECT * FROM annotations WHERE id=?", (annotation_id,)).fetchone())
    HUB.publish({"type": "annotation", "operation": "upsert", "revision": revision, "item": item})
    return item


